vec2 GetTorusUV(vec3 p, vec2 torusSize)
{
float x = atan(p.x, p.z);
float y = atan(length(p.xz)-torusSize.x, p.y);
return vec2(x,y);
}
float sdTorus1(vec3 p, vec2 r, float a) {
float torusDist = length( vec2(length(p.xz) - r.x, p.y) ) - r.y;
vec2 tUV = GetTorusUV(p, torus1Size());
vec4 h = HexCoords(tUV*vec2( 6.0 ,3.03) + 1000.0 + torusRotSpeed());
float hive = 0.25*smoothstep(0.,0.1,h.y) - 0.4*smoothstep(0.1,0.2,h.y); // + 0.0 * (3.0 * h.y)%2 + h.y*(sin(5.0 * uTime) ) * 0.0  + 0.1*0 + 0*0.5*cos(h.y * 10.0 + 0.3*q6);
float hexTorus = torusDist + hive;
float holesTorus = max(-hexTorus,torusDist);
float hiveTorus = q14*hexTorus;
float toreturn;
if(a == 1)
toreturn = holesTorus;
else
toreturn = hiveTorus;
return toreturn;
}
vec2 GetSphereUV(vec3 p, float r)
{
vec3 n = normalize(p);
float x = atan(n.x, n.z)/(2.*PI) + 0.5;
float y = 0.5 + 0.5*n.y;
return vec2(x,y);
}
float sdSphere( vec3 p, float r)
{
vec2 sUV = GetSphereUV(p, r);
vec2 h = HexCoords(sUV*vec2(6.,3.3) + 100.);
float sphereDist = length(p)-r;
float hive = -0.25*smoothstep(0.,0.1,h.y) + 0.4*smoothstep(0.1,0.2,h.y);
float HexSphere = sphereDist + hive; // + 0.3*h.y*sin(h.y*15. + uTime) - h.y
return max(-sphereDist,HexSphere);
}
vec2 GetDist(vec3 p, float a)
{
vec2 distToReturn;
// torus
vec3 torusPosNew = RotY(p - torus1Pos(), uTime);
//vec3 pNew = RotY(p, q26*1.5);
float torusDist = sdTorus1(p - torus1Pos(), torus1Size(), a);
float torusID = 2;
// a sphere inside the torus
vec3 spherePosNew = RotZ(spherePos(), uTime); // rotate around the torus
//spherePosNew = RotY(spherePosNew, uTime);
// rotate around itself
//spherePosNew = RotZ(p - spherePosNew, uTime);
//spherePosNew = RotY(spherePosNew, uTime);
float sphereDist = sdSphere(p-spherePos(), sphereRad());
float sphereID = 3.;
float dist = torusDist;//min(torusDist, sphereDist);
if(dist == torusDist)
distToReturn = vec2(torusDist, torusID);
if(dist == sphereDist)
distToReturn = vec2(sphereDist, sphereID);
return distToReturn;
}
vec3 RayMarch(vec3 ro, vec3 rd, float steps, float a)
{
vec2 dS;
float dO;
vec3 p;
float breakloop = 0;
for(int i = 0; i<steps && breakloop == 0; i++)
{
p = ro + rd * dO;
dS = GetDist(p, a);
if(dS.x < 0.0001) {breakloop = 1; }
dO += dS.x*0.5;
}
return vec3(dO,dS);
}
vec3 GetNormal(vec3 p, float a)
{
float d = GetDist(p, a).x;
vec2 e = vec2(.01, 0.0 );
vec3 n = d-vec3(GetDist(p-e.xyy, a).x,
GetDist(p-e.yxy, a).x,
GetDist(p-e.yyx, a).x);
return normalize(n);
}
float GetLight(vec3 p, vec3 n, vec3 lightpos, float lightpower, float shadowstrength, float steps, float a)
{
//vec3 lightpos = LightPos;
//lightpos = camerapos;
vec3 l = normalize(lightpos - p);
//vec3 n = GetNormal(p, a);
float dif = clamp(dot(n, l*lightpower), 0., 1.);
//dif = dot(n,l);
//float d = RayMarch(p + n*0.2, l, steps, a);
//if(d < length(lightpos-p)) {dif *= shadowstrength;}
return dif;
}
float specularReflection(vec3 p, vec3 N, vec3 rd, vec3 lightPos, float intensity, float shininessVal)
{
//vec3 N = GetNormal(p);
vec3 L = normalize(lightPos - p);
float lambertian = max(dot(L, N), 0.0);
float specular = 0.;
if(lambertian > 0.0) {
vec3 R = reflect(-L, N);      // Reflected light vector
vec3 V = normalize(-rd); // Vector to viewer
// Compute the specular term
float specAngle = max(dot(R, V), 0.0);
specular = pow(specAngle, shininessVal);
}
return specular * intensity;
}
vec3 applyFog( vec3 rgb, float distance, float strength)
{
float fogAmount = 1.0 - exp( -distance*strength );
vec3 fogColor = vec3(q3, 0.0 , q2);//vec3(1., 0.3, 0.8);
return mix( rgb, fogColor, fogAmount );
}
