//col += c2*normalize(float3(3,1.4,0));
//col += (1-c3)*normalize(float3(4,1.4,0));
//return c;
float b1 = 0.5 + 0.43*sin(hc.z*5 + hc.w*3 + 2*time);
float b2 = 0.5 + 0.5*cos(hc.y*65 + 3*time);
float4 ehc = HexCoords((hc+0.1*float2(0, time))*3*float2(2.0693,2.5) + 100 + float2(4,0));
float hexagons = smoothstep(0.,0.1, ehc.y)*((ehc.z)%2)*((ehc.w)%2);
float b3 = b1;//*(1-hexagons);
float edges = 1-c;
/*   float everyOtherTile = hc.z%2;
if( everyOtherTile == 0 ) {
everyOtherTile = 0; }
else if( everyOtherTile == 1 ) {
everyOtherTile = 1; }
else {everyOtherTile = 0.5;}
*/
float eSquares = cos(hc.y*20 + time)*sin(hc.x*20 + time); // edges squares
eSquares = smoothstep(0,0.01,eSquares);
float b4 = edges * eSquares;
//float b4 = edges * eHexagons;
col = hexagons*(1-b3)*c*float3(0.4274,0.847,0.8941) // azur color for the inverse of the waves
+ b3*c*float3(0.4078,0.1725,0.0705)  // brown color for the waves
+ float3(b3,0,(1-b3))*c*0.3          // add some rg colors to the waves and to the inverse of them
+ b4*float3(0.8431,0.7607,0.5019);   // brown-ish color for the ripples
//float3 test = float3(hc.zw*0.005,0);//everyOtherTile;
return col;
}
float2 GetTorusUV(float3 p, float2 torusSize)
{
float x = atan2(p.x, p.z);
float y = atan2(length(p.xz)-torusSize.x, p.y);
return float2(x,y);
}
float sdTorus1(float3 p, float2 r, float a) {
float torusDist = length( float2(length(p.xz) - r.x, p.y) ) - r.y;
float2 tUV = GetTorusUV(p, torus1Size());
float4 h = HexCoords(tUV*float2(6,3.03) + 1000 + torusRotSpeed());
float hive = 0.25*smoothstep(0.,0.1,h.y) - 0.4*smoothstep(0.1,0.2,h.y); // + 0*(3*h.y)%2 + h.y*(sin(5*time) )*0  + 0.1*0 + 0*0.5*cos(h.y*10 + 0.3*q6);
float hexTorus = torusDist + hive;
float holesTorus = max(-hexTorus,torusDist);
float hiveTorus = q14*hexTorus;
float toreturn;
if(a == 1)
toreturn = holesTorus;
else
toreturn = hiveTorus;
