float2 GetSphereUV(float3 p, float r)
{
float3 n = normalize(p);
float x = atan2(n.x, n.z)/(2.*PI) + 0.5;
float y = 0.5 + 0.5*n.y;
return float2(x,y);
}
float sdSphere( float3 p, float r)
{
float2 sUV = GetSphereUV(p, r);
float2 h = HexCoords(sUV*float2(6.,3.3) + 100.);
float sphereDist = length(p)-r;
float hive = -0.25*smoothstep(0.,0.1,h.y) + 0.4*smoothstep(0.1,0.2,h.y);
float HexSphere = sphereDist + hive; // + 0.3*h.y*sin(h.y*15. + time) - h.y
return max(-sphereDist,HexSphere);
}
float2 GetDist(float3 p, float a)
{
float2 distToReturn;
// torus
float3 torusPosNew = RotY(p - torus1Pos(), time);
//float3 pNew = RotY(p, q26*1.5);
float torusDist = sdTorus1(p - torus1Pos(), torus1Size(), a);
float torusID = 2;
// a sphere inside the torus
float3 spherePosNew = RotZ(spherePos(), time); // rotate around the torus
//spherePosNew = RotY(spherePosNew, time);
// rotate around itself
//spherePosNew = RotZ(p - spherePosNew, time);
//spherePosNew = RotY(spherePosNew, time);
float sphereDist = sdSphere(p-spherePos(), sphereRad());
float sphereID = 3.;
float dist = torusDist;//min(torusDist, sphereDist);
if(dist == torusDist)
distToReturn = float2(torusDist, torusID);
if(dist == sphereDist)
distToReturn = float2(sphereDist, sphereID);
return distToReturn;
}
float3 RayMarch(float3 ro, float3 rd, float steps, float a)
{
float2 dS;
float dO;
float3 p;
float breakloop = 0;
for(int i = 0; i<steps && breakloop == 0; i++)
{
p = ro + rd * dO;
dS = GetDist(p, a);
if(dS.x < 0.0001) {breakloop = 1; }
dO += dS.x*0.5;
}
return float3(dO,dS);
}
float3 GetNormal(float3 p, float a)
{
float d = GetDist(p, a).x;
float2 e = float2(.01, 0);
float3 n = d-float3(GetDist(p-e.xyy, a).x,
GetDist(p-e.yxy, a).x,
GetDist(p-e.yyx, a).x);
return normalize(n);
}
float GetLight(float3 p, float3 n, float3 lightpos, float lightpower, float shadowstrength, float steps, float a)
{
//float3 lightpos = LightPos;
//lightpos = camerapos;
float3 l = normalize(lightpos - p);
//float3 n = GetNormal(p, a);
float dif = clamp(dot(n, l*lightpower), 0., 1.);
//dif = dot(n,l);
//float d = RayMarch(p + n*0.2, l, steps, a);
//if(d < length(lightpos-p)) {dif *= shadowstrength;}
return dif;
}
float specularReflection(float3 p, float3 N, float3 rd, float3 lightPos, float intensity, float shininessVal)
{
//float3 N = GetNormal(p);
float3 L = normalize(lightPos - p);
float lambertian = max(dot(L, N), 0.0);
float specular = 0.;
if(lambertian > 0.0) {
float3 R = reflect(-L, N);      // Reflected light vector
float3 V = normalize(-rd); // Vector to viewer
// Compute the specular term
float specAngle = max(dot(R, V), 0.0);
specular = pow(specAngle, shininessVal);
}
return specular * intensity;
}
float3 applyFog( float3 rgb, float distance, float strength)
{
float fogAmount = 1.0 - exp( -distance*strength );
float3 fogColor = float3(q3, 0, q2);//float3(1., 0.3, 0.8);
return lerp( rgb, fogColor, fogAmount );
}
