float glow, tmp, lamp, dist, bdist, b2dist, dist_c, smask;
float2 dz, uv1, uv3, uv4;
static const float3 CamPos = float3(q4,q5,q6);
static const float myzoom = q7,  res = 255, res2 = 64, tele = q16;
static const float3x3 RotMat = float3x3(q20,q21,q22,q23,q24,q25,q26,q27,q28);
float2 fstep2 (float2 xy) {return 1.0/res*round(res*xy);}
float GetDist(float2 uvi) {float2 tmp; tmp = (tex2D (sampler_fc_main, uvi).gb);
return 1.0078125-tmp.y -0.015625*tmp.x;} // = 1-(tmp.y + 1.0/res2*(tmp.x-.50));}
float GetDistB(float2 uvi)  {return 1-GetBlur1(uvi).b;}
float3 screen3;
float3 lavcol (float t) {return saturate(float3(pow(t,1),pow(t,2.),pow(t,5)));}
static float3 t = float3(q20,q23,q26);
static float3 s = float3(q21,q24,q27);
static float3 ts = -cross(s,t);
static float3 pos = float3 (1,1,1);
float3 project (float dist) {  float z;
z = 18*dist/mul(cross(ts,-t),screen3);
return float3(mul(float2x3(ts,t),cross(pos,screen3))-z,-z);}
shader_body {
screen3 = float3 ((uv-.5)*aspect.xy,tele*0+1);
