float3 sky = sat(lavcol (1-(abs(.3/uv2.z))))-.8;
bdist = min(GetDist(uv),GetDistB(uv));;
sky *= sat(1*bdist-2);
ret = sat(lerp (1, sky, bdist));
float struc = lerp(GetPixel(uv).r, GetBlur1((uv-5)/5+5).r,GetBlur1(uv).r-.8);
ret += lavcol(struc)*(.2-pow(bdist,1+5*mid_att));
